-- Link GRNs to supplier purchase orders and maintain receipt status.
alter table public.grns add column purchase_order_id uuid references public.purchase_orders(purchase_order_id);
create index idx_grns_purchase_order on public.grns(purchase_order_id);
create or replace function public.post_factory_po_grn(p_purchase_order uuid,p_ownership text,p_driver text,p_vehicle text,p_lines jsonb,p_received_by text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_grn uuid;v_supplier uuid;v_status text;v_ordered numeric;v_received numeric;begin if not has_factory_role(auth.uid(),array['admin','store'])then raise exception'not authorized';end if;select supplier_id,status into v_supplier,v_status from purchase_orders where purchase_order_id=p_purchase_order for update;if v_supplier is null or v_status not in('ISSUED','PART_RECEIVED')then raise exception'purchase order is not open for receiving';end if;select post_factory_grn(v_supplier,p_ownership,p_driver,p_vehicle,p_lines,p_received_by)into v_grn;update grns set purchase_order_id=p_purchase_order,updated_at=now(),updated_by=auth.uid()::text where grn_id=v_grn;select coalesce(sum(quantity),0)into v_ordered from purchase_order_lines where purchase_order_id=p_purchase_order;select coalesce(sum(l.qty),0)into v_received from grns g join grn_lines l using(grn_id)where g.purchase_order_id=p_purchase_order and g.status='POSTED';update purchase_orders set status=case when v_received>=v_ordered then'RECEIVED'else'PART_RECEIVED'end,updated_at=now(),updated_by=auth.uid()::text where purchase_order_id=p_purchase_order;insert into audit_log(user_id,action,entity_type,entity_id,new_value)values(auth.uid(),'Purchase Order Receipt','purchase_orders',p_purchase_order,jsonb_build_object('grn_id',v_grn,'ordered_quantity',v_ordered,'received_quantity',v_received));return v_grn;end$$;
grant execute on function public.post_factory_po_grn(uuid,text,text,text,jsonb,text)to authenticated;
